// Milestone 10 UI preview against the LOCAL Supabase stack (web render, decision #52): the
// superintendent's daily company report (generated by the real daily-reports function), the
// foreman's answer (dispute through report-confirm), the corrected version 2, the worker's own
// hours and correction request, correction requests for staff, foreman kiosk access, Spanish.
// The share sheet itself is native only (checklist "Real-device reports and CSV share check").
const { chromium } = require('playwright');
const { Buffer } = require('node:buffer');
const { createHmac, randomUUID } = require('node:crypto');
const path = require('node:path');

const { Client } = require(path.join(process.cwd(), 'node_modules', 'pg'));

const [base, out] = process.argv.slice(2);
const viewport = { width: 390, height: 844 };
const byTestId = (page, id) => page.locator(`[data-testid="${id}"]:visible`).first();

async function shot(page, name, scrollTo) {
  if (scrollTo) await byTestId(page, scrollTo).scrollIntoViewIfNeeded();
  await page.waitForTimeout(800);
  await page.screenshot({ path: `${out}/${name}.png` });
  console.log(`captured ${name}.png`);
}

async function query(sql, params) {
  const db = new Client({ connectionString: process.env.DB_URL });
  await db.connect();
  try {
    return (await db.query(sql, params)).rows;
  } finally {
    await db.end();
  }
}

async function latestEmailCode(address) {
  for (let i = 0; i < 40; i += 1) {
    const search = await (
      await fetch(
        `${process.env.MAILPIT_URL}/api/v1/search?query=${encodeURIComponent(`to:"${address}"`)}`,
      )
    ).json();
    if (search.messages[0]) {
      const message = await (
        await fetch(`${process.env.MAILPIT_URL}/api/v1/message/${search.messages[0].ID}`)
      ).json();
      const code = `${message.Text} ${message.HTML}`.match(/\b(\d{6})\b/);
      if (code) return code[1];
    }
    await new Promise((resolve) => setTimeout(resolve, 250));
  }
  throw new Error('no email code');
}

function totp(secretBase32) {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  let bits = '';
  for (const char of secretBase32.replace(/\s|=/g, '').toUpperCase())
    bits += alphabet.indexOf(char).toString(2).padStart(5, '0');
  const key = Buffer.from(bits.match(/.{8}/g).map((byte) => parseInt(byte, 2)));
  const counter = Buffer.alloc(8);
  counter.writeBigUInt64BE(BigInt(Math.floor(Date.now() / 30000)));
  const digest = createHmac('sha1', key).update(counter).digest();
  const offset = digest[digest.length - 1] & 0x0f;
  return String((digest.readUInt32BE(offset) & 0x7fffffff) % 1000000).padStart(6, '0');
}

async function staffSignIn(page, email) {
  await page.goto(base);
  await byTestId(page, 'choose-en-US').click();
  await byTestId(page, 'staff-sign-in').click();
  await byTestId(page, 'email-input').fill(email);
  await byTestId(page, 'send-email-code').click();
  await byTestId(page, 'email-code-input').fill(await latestEmailCode(email));
  await byTestId(page, 'verify-email-code').click();
  await byTestId(page, 'mfa-secret').waitFor();
  const secret = await byTestId(page, 'mfa-secret').innerText();
  await byTestId(page, 'mfa-code-input').fill(totp(secret));
  await byTestId(page, 'mfa-confirm').click();
  await byTestId(page, 'no-org-screen').waitFor();
}

async function workerSignIn(page, locale) {
  await page.goto(base);
  await byTestId(page, `choose-${locale}`).click();
  await byTestId(page, 'worker-sign-in').click();
  const local = String(Math.floor(Math.random() * 9000000) + 1000000);
  await byTestId(page, 'phone-input').fill(`(555) ${local.slice(0, 3)}-${local.slice(3)}`);
  await byTestId(page, 'send-code').click();
  await byTestId(page, 'code-input').waitFor();
  const rows = await query(
    'select otp from app_private.dev_sms_outbox where phone = $1 order by id desc limit 1',
    [`1555${local}`],
  );
  await byTestId(page, 'code-input').fill(rows[0].otp);
  await byTestId(page, 'verify-code').click();
  await byTestId(page, 'join-screen').waitFor();
  return local;
}

async function openTab(page, href) {
  await page
    .locator(`[href="${href}"]:visible`)
    .first()
    .click()
    .catch(async (error) => {
      await page.screenshot({ path: `${out}/debug-tab.png` });
      console.error('url:', page.url(), (await page.locator('body').innerText()).slice(0, 600));
      throw error;
    });
}

/** Closed visits on a project-local date (HH:MM local), recorded by the foreman. */
async function visit(projectId, workerId, companyId, localDate, from, to) {
  await query(
    `insert into public.attendance_sessions (id, project_id, worker_id, employer_snapshot_id, start_at, end_at, start_source,
                                             end_source, config_version_id, status, iana_timezone, last_seen_at, witnessed,
                                             start_confidence, opened_by_event)
     select $1, p.id, $2, $3, ($4::date + $5::time) at time zone p.iana_timezone, ($4::date + $6::time) at time zone p.iana_timezone,
            'FOREMAN', 'FOREMAN', p.config_version_id, 'CLOSED', p.iana_timezone,
            ($4::date + $6::time) at time zone p.iana_timezone, true, 'HIGH', gen_random_uuid()
       from public.projects p where p.id = $7`,
    [randomUUID(), workerId, companyId, localDate, from, to, projectId],
  );
}

async function main() {
  const browser = await chromium.launch();
  try {
    const staffContext = await browser.newContext({
      viewport,
      deviceScaleFactor: 2,
      locale: 'en-US',
    });
    const staff = await staffContext.newPage();
    const ownerEmail = `owner.m10.${Date.now()}@example.test`;
    await staffSignIn(staff, ownerEmail);
    await byTestId(staff, 'create-organization').click();
    await byTestId(staff, 'org-name').fill('Gulf Coast Builders');
    await byTestId(staff, 'org-create').click();
    await byTestId(staff, 'new-project').click();
    await byTestId(staff, 'project-name').fill('Main Street Tower');
    await byTestId(staff, 'wizard-next').click();
    await byTestId(staff, 'address-query').fill('100 Main St');
    await byTestId(staff, 'address-candidate-0').click();
    await byTestId(staff, 'selected-address').waitFor();
    await byTestId(staff, 'wizard-next').click();
    await byTestId(staff, 'timezone-America/Chicago').click();
    await byTestId(staff, 'wizard-next').click();
    await byTestId(staff, 'wizard-create').click();
    await byTestId(staff, 'status-ACTIVE').click();
    await byTestId(staff, 'confirm-status').click();
    await byTestId(staff, 'run-orientation').click();
    await byTestId(staff, 'orientation-start').click();
    await byTestId(staff, 'orientation-rotating-qr').waitFor();

    // Ana joins with the orientation code, is approved and is her company's verified foreman.
    const workerContext = await browser.newContext({
      viewport,
      deviceScaleFactor: 2,
      locale: 'en-US',
    });
    const worker = await workerContext.newPage();
    await workerSignIn(worker, 'en-US');
    const [{ code }] = await query(
      "select 'SMS1.' || session_id || '.' || static_code as code from app_private.orientation_session_secrets order by created_at desc limit 1",
    );
    await byTestId(worker, 'join-type').click();
    await byTestId(worker, 'join-code-input').fill(code);
    await byTestId(worker, 'join-code-submit').click();
    await byTestId(worker, 'details-name').fill('Ana Acosta');
    await byTestId(worker, 'details-company-name').fill('Southern Concrete');
    await byTestId(worker, 'details-trade').fill('Concrete');
    await byTestId(worker, 'details-emergency-name').fill('Luis Acosta');
    await byTestId(worker, 'details-emergency-phone').fill('+1 555 000 2222');
    await byTestId(worker, 'details-emergency-relationship').fill('Brother');
    await byTestId(worker, 'join-next').click();
    await byTestId(worker, 'notice-view').waitFor();
    await byTestId(worker, 'join-acknowledge').click();
    await byTestId(worker, 'join-submit').scrollIntoViewIfNeeded();
    await worker.waitForTimeout(700);
    await byTestId(worker, 'join-submit').click();
    await byTestId(worker, 'join-done').waitFor();
    await byTestId(worker, 'join-home').click();
    await worker.locator('[data-testid^="enrollment-status-"]:visible').first().waitFor();
    await byTestId(staff, 'orientation-to-workers').click();
    await byTestId(staff, 'select-all').click();
    await byTestId(staff, 'approve-selected').click();
    await byTestId(staff, 'bulk-results').waitFor();

    const [{ project_id: projectId, company_id: companyId, ana }] = await query(
      `select p.id as project_id, e.subcontractor_id as company_id, e.worker_id as ana
         from public.projects p join public.organizations o on o.id = p.organization_id
         join auth.users u on u.id = o.owner_user_id and u.email = $1
         join public.worker_enrollments e on e.project_id = p.id
        order by p.created_at desc limit 1`,
      [ownerEmail],
    );
    await query(
      "update public.worker_enrollments set employer_status = 'VERIFIED', employer_confirmed_at = now() where project_id = $1",
      [projectId],
    );
    await query(
      "update public.project_subcontractors set status = 'APPROVED' where project_id = $1 and subcontractor_id = $2",
      [projectId, companyId],
    );
    await query(
      `insert into public.subcontractor_members (company_id, worker_profile_id, role, verification_status)
       values ($1, $2, 'FOREMAN', 'VERIFIED')
       on conflict do nothing`,
      [companyId, ana],
    );
    const [{ ben }] = await query(
      `with w as (insert into public.worker_profiles (legal_name, managed_identity) values ('Ben Avila', true) returning id),
            n as (select id from public.legal_notice_versions where document_id = 'WORKER_LOCATION_DISCLOSURE_EN_V1'),
            o as (insert into public.orientation_records (worker_profile_id, project_id, completed_at, notice_version_id)
                  select w.id, $1, now(), n.id from w, n returning worker_profile_id),
            e as (insert into public.worker_enrollments (project_id, worker_id, subcontractor_id, trade, enrollment_status, employer_status, employer_confirmed_at, approval_at)
                  select $1, o.worker_profile_id, $2, 'Concrete', 'APPROVED', 'VERIFIED', now(), now() from o returning worker_id)
       select worker_id as ben from e`,
      [projectId, companyId],
    );
    const [{ yesterday, monday, tuesday }] = await query(
      `select ((now() at time zone 'America/Chicago')::date - 1)::text as yesterday,
              (date_trunc('week', (now() at time zone 'America/Chicago')::date) - interval '7 days')::date::text as monday,
              (date_trunc('week', (now() at time zone 'America/Chicago')::date) - interval '6 days')::date::text as tuesday`,
    );
    await visit(projectId, ana, companyId, yesterday, '07:00', '15:00');
    await visit(projectId, ben, companyId, yesterday, '07:00', '16:00');
    await visit(projectId, ana, companyId, monday, '06:45', '15:15');
    await visit(projectId, ana, companyId, tuesday, '07:00', '14:30');

    // Superintendent: the daily company report for yesterday (generated on first open). The
    // preview server has no deep links: navigate inside the app (browser back works).
    await staff.goBack();
    await staff.goBack();
    await byTestId(staff, 'open-reports').click();
    await byTestId(staff, `report-${companyId}`).waitFor({ timeout: 20000 });
    await shot(staff, '01-staff-daily-report-en');

    // Foreman Ana: the report waiting for an answer, then a dispute.
    await openTab(worker, '/worker/projects');
    await openTab(worker, '/worker/home');
    await byTestId(worker, 'foreman-reports-open').click();
    await byTestId(worker, `report-${companyId}`).waitFor({ timeout: 20000 });
    const reportId = await worker
      .locator('[data-testid^="confirm-"]:visible')
      .first()
      .getAttribute('data-testid');
    const id = String(reportId).replace('confirm-', '');
    await byTestId(worker, `answer-mode-${id}-DISPUTE`).click();
    await byTestId(worker, `answer-reason-${id}`).fill('Ben left at noon, not 4 pm');
    await shot(worker, '02-foreman-answer-en', `answer-mode-${id}`);
    await byTestId(worker, `answer-send-${id}`).click();
    await byTestId(worker, 'answer-done').waitFor();
    await shot(worker, '03-foreman-dispute-sent-en');

    // Superintendent: the dispute is shown; a corrected version 2 keeps version 1 and its answer.
    await staff.goBack();
    await byTestId(staff, 'open-reports').click();
    await staff.getByText('Disputed by foreman').first().waitFor({ timeout: 20000 });
    await byTestId(staff, `reissue-${companyId}`).click();
    await byTestId(staff, `reissue-reason-${companyId}`).fill(
      'Ben left at noon (correction approved)',
    );
    await byTestId(staff, `reissue-confirm-${companyId}`).click();
    await byTestId(staff, `report-earlier-${companyId}`).waitFor({ timeout: 20000 });
    await shot(staff, '04-staff-version-2-en', `report-earlier-${companyId}`);

    // Worker Ana: her own hours last week and a correction request.
    await byTestId(worker, 'foreman-reports-back').click();
    await openTab(worker, '/worker/history');
    await byTestId(worker, 'hours-week-previous').click();
    await byTestId(worker, 'hours-total').waitFor({ timeout: 20000 });
    await shot(worker, '05-worker-hours-en');
    await byTestId(worker, 'hours-request-open').click();
    await worker.locator('[data-testid^="hours-request-target-"]:visible').first().click();
    await byTestId(worker, 'hours-request-end').fill('16:00');
    await byTestId(worker, 'hours-request-reason').fill('I stayed to clean up until 4 pm');
    await shot(worker, '06-worker-request-en', 'hours-request-form');
    await byTestId(worker, 'hours-request-send').click();
    await byTestId(worker, 'hours-request-sent').waitFor();

    // Superintendent: correction requests and foreman kiosk access.
    await byTestId(staff, 'open-requests').click();
    await staff.locator('[data-testid^="request-"]:visible').first().waitFor({ timeout: 20000 });
    await shot(staff, '07-staff-requests-en');
    await staff.goBack();
    await staff.goBack();
    await byTestId(staff, 'open-foremen').click();
    await staff.locator('[data-testid^="grant-"]:visible').first().waitFor({ timeout: 20000 });
    await shot(staff, '08-staff-kiosk-access-en');

    // Spanish: the worker's hours.
    await openTab(worker, '/worker/profile');
    await byTestId(worker, 'language-switch-es-US').click();
    await openTab(worker, '/worker/history');
    await byTestId(worker, 'hours-week-previous').click();
    await worker
      .getByText('Total de la semana', { exact: false })
      .first()
      .waitFor({ timeout: 20000 });
    await shot(worker, '09-worker-hours-es');
  } finally {
    await browser.close();
  }
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
